18: // extractJSON extracts the JSON portion from output that may contain INFO messages
19: func extractJSON(output string) string {
20: 	// Find the JSON object (starts with { and ends with })
21: 	start := strings.Index(output, "{")
22: 	if start == -1 {
23: 		return output
24: 	}
25: 	// Find matching closing brace
26: 	depth := 0
27: 	for i := start; i < len(output); i++ {
28: 		switch output[i] {
29: 		case '{':
30: 			depth++
31: 		case '}':
32: 			depth--
33: 			if depth == 0 {
34: 				return output[start : i+1]
35: 			}
36: 		}
37: 	}
38: 	return output[start:]
39: }
